{"rfp_id": "3202600157", "requirements": [
{"id": "R-001", "verbatim_text": "Participation in a post-award orientation will be required before any services related to the awarded Contract can be performed.", "section_ref": "6.1", "type": "shall", "category": "deliverable", "due_date": null, "page": 40},
{"id": "R-002", "verbatim_text": "Provider(s) must comply with the Article II Scope of Work, VR-SFP Manual Chapter 3: Basic Standards, and any other applicable sections of the VR-SFP Manual.", "section_ref": "6.3", "type": "shall", "category": "deliverable", "due_date": null, "page": 40},
{"id": "R-003", "verbatim_text": "The Contract may be amended only by written agreement signed by both the Provider and TWC.", "section_ref": "6.4", "type": "info", "category": "deliverable", "due_date": null, "page": 40},
{"id": "R-004", "verbatim_text": "Providers must maintain insurance as described in VR-SFP Chapter 3 when insurance requirements are applicable.", "section_ref": "6.9", "type": "shall", "category": "deliverable", "due_date": null, "page": 42},
{"id": "R-005", "verbatim_text": "The Provider and any of its subcontractors associated with the Contract will remedy in a timely manner any weaknesses, deficiencies, or program noncompliance found as a result of a review, audit or investigation, and any performance or fiscal exceptions found by TWC, the SAO, the federal funding agency, their successor agencies, or any of their duly authorized representatives.", "section_ref": "6.11", "type": "shall", "category": "deliverable", "due_date": null, "page": 43},
{"id": "R-006", "verbatim_text": "During the term of the Contract or any extension or renewal thereof, the Provider shall notify TWC in writing of any substantial change in the ownership or control of the Provider as soon as possible, but no later than thirty (30) days prior to its occurrence.", "section_ref": "6.12", "type": "shall", "category": "deliverable", "due_date": null, "page": 44},
{"id": "R-007", "verbatim_text": "Provider must also notify TWC in writing of any change in financial condition as soon as possible, but no later than ten (10) days after its occurrence.", "section_ref": "6.12", "type": "shall", "category": "deliverable", "due_date": null, "page": 44}
]}

{"rfp_id": "3202700013", "requirements": [
{"id": "R-001", "verbatim_text": "If Respondent asserts that information provided in its Response is exempt from disclosure under the Texas Public Information Act, Respondent must mark and submit two separate, searchable Portable Document Format (PDF) copies (Original Response and \"Public Information Act Copy,\" including attachments, of the Original Response) as identified below.", "section_ref": "5.11.1", "type": "shall", "category": "form", "due_date": null, "page": 44},
{"id": "R-002", "verbatim_text": "Within five (5) days from Contract execution, the Successful Respondent must submit a \"Public Information Act Copy\" of the Original Executed Contract (in addition to the original executed contract) to the TWC contract manager by email.", "section_ref": "5.11.2", "type": "shall", "category": "deliverable", "due_date": null, "page": 46},
{"id": "R-003", "verbatim_text": "For the duration of any Contract resulting from this Solicitation, the Successful Respondent shall acquire insurance, bonds, or both, with financially sound and reputable independent insurers, in the type and amount listed in Attachment 2 - Insurance Requirements.", "section_ref": "6.8", "type": "shall", "category": "deliverable", "due_date": null, "page": 49},
{"id": "R-004", "verbatim_text": "The Response must include a certification that the entity is not for sale or to become acquired by another business entity during the twelve (12) months following the Response Deadline.", "section_ref": "6.11", "type": "shall", "category": "deliverable", "due_date": null, "page": 53},
{"id": "R-005", "verbatim_text": "During the term of the Contract or any extension or renewal thereof, the Successful Respondent shall notify TWC in writing of any substantial change in the ownership or control of the Successful Respondent as soon as possible, but no later than thirty (30) days prior to its occurrence.", "section_ref": "6.11", "type": "shall", "category": "deliverable", "due_date": null, "page": 53},
{"id": "R-006", "verbatim_text": "Successful Respondent must also notify TWC in writing of any change in financial condition as soon as possible, but no later than ten (10) days after its occurrence.", "section_ref": "6.11", "type": "shall", "category": "deliverable", "due_date": null, "page": 53},
{"id": "R-007", "verbatim_text": "The Contract Term will commence on the fully executed Contract date and expire on September 24, 2027, or October 1, 2027 (depending on which conference dates are selected).", "section_ref": "6.2", "type": "info", "category": "deadline", "due_date": null, "page": 47}
]}

{"rfp_id": "HHS0017298", "requirements": [
{"id": "R-001", "verbatim_text": "Contractors, Respondents, and Vendors interested in working with HHSC are required to implement standards of conduct for their own personnel and agents on terms at least as restrictive as those applicable to HHSC ... A Respondent must sign and submit all ethics, disclosure, confidentiality, and other forms required under the procurement and any resulting contract.", "section_ref": "8.1.7", "type": "shall", "category": "form", "due_date": null, "page": 29},
{"id": "R-002", "verbatim_text": "Pursuant to Section 2252.908 of the Texas Government Code, the Respondent to be awarded a contract with a value of $1 million or more or awarded a contract that would require the Respondent to register as a lobbyist under Chapter 305 of the Texas Government Code must submit a disclosure of interested parties form to HHSC at the time the Respondent submits the signed Contract.", "section_ref": "8.1.8", "type": "shall", "category": "form", "due_date": null, "page": 30},
{"id": "R-003", "verbatim_text": "For the Contract Term, the Contractor shall acquire insurance with financially sound and reputable independent insurers, in the type and amount listed in Exhibit C, Sample OAG Outside Counsel Contract. Failure to maintain insurance coverage or acceptable alternative methods of insurance shall be deemed a breach of contract.", "section_ref": "8.2.1", "type": "shall", "category": "eligibility", "due_date": null, "page": 30},
{"id": "R-004", "verbatim_text": "RESPONDENT SHALL DEFEND, INDEMNIFY, AND HOLD HARMLESS THE STATE OF TEXAS AND HHSC, AND/OR THEIR OFFICERS, AGENTS, EMPLOYEES, REPRESENTATIVES, CONTRACTORS, ASSIGNEES, AND/OR DESIGNEES FROM ANY AND ALL LIABILITY, ACTIONS, CLAIMS, DEMANDS, OR SUITS, AND ALL RELATED COSTS, ATTORNEY FEES, AND EXPENSES ARISING OUT OF, OR RESULTING FROM ANY ACTS OR OMISSIONS OF RESPONDENT OR ITS AGENTS, EMPLOYEES, SUBCONTRACTORS, ORDER FULFILLERS, OR SUPPLIERS OF SUBCONTRACTORS IN THE EXECUTION OR PERFORMANCE OF THE CONTRACT AND ANY PURCHASE ORDERS ISSUED UNDER THE CONTRACT.", "section_ref": "8.4", "type": "shall", "category": "eligibility", "due_date": null, "page": 31}
]}

{"rfp_id": "HHS0017691", "requirements": [
{"id": "R-001", "verbatim_text": "Provide any other information Bidder believes is pertinent to demonstrate the Bidder's financial capability, financial solvency, and capacity to fulfill the requirements of this IFB.", "section_ref": "Appendix A.4", "type": "info", "category": "form", "due_date": null, "page": 38},
{"id": "R-002", "verbatim_text": "Addendum Acknowledgement Form(s), if applicable", "section_ref": "Appendix A.4", "type": "info", "category": "form", "due_date": null, "page": 38},
{"id": "R-003", "verbatim_text": "Public Information Act Copy of Response, if applicable. Reference Section 12.7 Public Information Act – Bidder Requirements Regarding Disclosure.", "section_ref": "Appendix A.4", "type": "info", "category": "form", "due_date": null, "page": 38}
]}
